"sp_calcular_balance_flujos": "CREATE   PROCEDURE [inventar_SpcHidr].[sp_calcular_balance_flujos]
(
    @fecha_inicio date,
    @fecha_fin    date,
    @modelo_id   int = 1,
    /* Solo para diagnostico manual desde SSMS. En 0 (por defecto) el
       procedimiento devuelve UN unico resultset, el de la seccion 9.
       En 1 agrega un segundo resultset con el detalle de ajustes acotados;
       no usar desde la aplicacion, que lee el primer resultset. */
    @debug_acotados bit = 0
)
AS
BEGIN
    SET NOCOUNT ON;
    -------------------------------------------------------------------------
    -- 0) NORMALIZAR FECHAS
    -------------------------------------------------------------------------
    IF @fecha_inicio > @fecha_fin
    BEGIN
        DECLARE @tmp date = @fecha_inicio;
        SET @fecha_inicio = @fecha_fin;
        SET @fecha_fin = @tmp;
    END;
    DECLA

